{"file":"restart_2026_11_26/fulltext_retrieval/retrieval_log.csv","fields":["screening_id","decision","status","reason_if_no_pdf"],"role":"Anchors sought-for-retrieval records by screening_id, abstract-stage decision (RETRIEVE_FULL_TEXT/UNCLEAR), full-text retrieval status (RETRIEVED_PDF/NOT_RETRIEVED), and non-retrieval reason (reason_if_no_pdf); does not provide full-text eligibility or study-family linkage (refer to fulltext_screening.csv and report_study_map.csv).","unresolved":null}
{"file":"restart_2026_11_26/fulltext_retrieval/missing_pdf.csv","fields":["screening_id","status","reason_if_no_pdf"],"role":"Anchors unretrieved full-text records by screening_id, retrieval status (NOT_RETRIEVED), and failure reason (reason_if_no_pdf); does not provide abstract-stage decision, full-text eligibility, or study-family linkage (refer to retrieval_log.csv for abstract-stage decision).","unresolved":null}
{"file":"restart_2026_11_26/fulltext_screening/fulltext_screening.csv","fields":["screening_id","decision","primary_reason_code","decision_reason","secondary_failure_codes","unresolved_codes"],"role":"Anchors full-text eligibility outcomes by screening_id, decision (INCLUDE/EXCLUDE/AWAITING_CLASSIFICATION), primary_reason_code, decision_reason, secondary_failure_codes, and unresolved_codes; does not provide abstract-stage status or study-family linkage (refer to retrieval_log.csv and report_study_map.csv).","unresolved":null}
{"file":"restart_2026_11_26/fulltext_screening/exclusions.csv","fields":["screening_id","decision","primary_reason_code","decision_reason","secondary_failure_codes","unresolved_codes"],"role":"Anchors full-text excluded records by screening_id, decision (EXCLUDE), primary_reason_code, decision_reason, secondary_failure_codes, and unresolved_codes; excludes INCLUDE/AWAITING_CLASSIFICATION outcomes and does not provide abstract-stage status or study-family linkage (refer to fulltext_screening.csv and report_study_map.csv).","unresolved":null}
{"file":"restart_2026_11_26/study_linkage/report_study_map.csv","fields":["report_id","study_id","linkage_status","pair_keys","group_member_reports"],"role":"Anchors included report-to-study family linkage by report_id, study_id, linkage_status, pair_keys, and group_member_reports; does not provide full-text eligibility decisions or abstract-stage status (refer to fulltext_screening.csv and retrieval_log.csv).","unresolved":null}
